-- BrightPAS 0.10.1/0.10.2 – cross-module integrity, reporting views, stored procedures and maintenance.
-- Hand-written (not generated by EF). Idempotent: safe to run on every install/upgrade. Runs after all module scripts.
-- Every table already has a clustered primary key (no heaps) – checked by the installer test "Database_has_no_heaps".

SET NOCOUNT ON;
GO

IF SCHEMA_ID(N'reporting') IS NULL EXEC(N'CREATE SCHEMA [reporting] AUTHORIZATION [dbo]');
IF SCHEMA_ID(N'maintenance') IS NULL EXEC(N'CREATE SCHEMA [maintenance] AUTHORIZATION [dbo]');
GO

-- ---------------------------------------------------------------------------------------------------------------
-- Cross-schema foreign keys (each module has its own schema/DbContext, so EF cannot declare these itself).
-- Existing orphan rows (e.g. sandbox data) do not block installation: the key is then created WITH NOCHECK
-- (still enforced for all new rows) and a warning is printed so the data can be tidied.
-- ---------------------------------------------------------------------------------------------------------------
CREATE OR ALTER PROCEDURE [maintenance].[usp_EnsureForeignKey]
    @Name sysname, @Table nvarchar(256), @Column sysname, @RefTable nvarchar(256), @RefColumn sysname = N'Id'
AS
BEGIN
    SET NOCOUNT ON;
    IF OBJECT_ID(@Table, N'U') IS NULL OR OBJECT_ID(@RefTable, N'U') IS NULL RETURN;
    IF EXISTS (SELECT 1 FROM sys.foreign_keys WHERE [name] = @Name AND parent_object_id = OBJECT_ID(@Table)) RETURN;
    DECLARE @orphans int, @sql nvarchar(max);
    SET @sql = N'SELECT @n = COUNT(*) FROM ' + @Table + N' c WHERE c.' + QUOTENAME(@Column) + N' IS NOT NULL AND NOT EXISTS (SELECT 1 FROM '
             + @RefTable + N' r WHERE r.' + QUOTENAME(@RefColumn) + N' = c.' + QUOTENAME(@Column) + N')';
    EXEC sp_executesql @sql, N'@n int OUTPUT', @n = @orphans OUTPUT;
    SET @sql = N'ALTER TABLE ' + @Table + CASE WHEN @orphans = 0 THEN N' WITH CHECK' ELSE N' WITH NOCHECK' END + N' ADD CONSTRAINT ' + QUOTENAME(@Name)
             + N' FOREIGN KEY (' + QUOTENAME(@Column) + N') REFERENCES ' + @RefTable + N' (' + QUOTENAME(@RefColumn) + N')';
    EXEC (@sql);
    IF @orphans > 0 PRINT N'WARNING: ' + @Name + N' created WITH NOCHECK – ' + CAST(@orphans AS nvarchar(20)) + N' existing row(s) in ' + @Table + N' have no matching ' + @RefTable + N'.';
END
GO

