-- ---------------------------------------------------------------------------------------------------------------
-- Reporting views (read-only, for Power BI / Excel / auditors). Merged duplicate patient records are excluded.
-- ---------------------------------------------------------------------------------------------------------------
CREATE OR ALTER VIEW [reporting].[vPatient] AS
SELECT p.[Id] AS PatientId, p.[Mrn], p.[Nhi], p.[FamilyName], p.[GivenNames], p.[PreferredName], p.[DateOfBirth], p.[Sex],
       DATEDIFF(year, p.[DateOfBirth], CAST(SYSDATETIME() AS date)) - CASE WHEN DATEADD(year, DATEDIFF(year, p.[DateOfBirth], CAST(SYSDATETIME() AS date)), p.[DateOfBirth]) > CAST(SYSDATETIME() AS date) THEN 1 ELSE 0 END AS AgeYears,
       p.[GpPracticeHpiFacilityId], p.[IsTestPatient], p.[CreatedAt]
FROM [patients].[Patients] p
WHERE p.[MergedIntoId] IS NULL;
GO

CREATE OR ALTER VIEW [reporting].[vTheatreCase] AS
SELECT b.[Id] AS BookingId, s.[Id] AS SessionId, s.[Date] AS ListDate, l.[Name] AS Room, s.[StartTime] AS ListStart, s.[EndTime] AS ListEnd, s.[Type] AS ListType,
       su.[Name] AS Surgeon, an.[Name] AS Anaesthetist, s.[SurgeonId], s.[AnaesthetistId], s.[IsCancelled] AS ListCancelled, b.[Order] AS CaseOrder, b.[PatientId], p.[Mrn], p.[Nhi], p.[FamilyName], p.[GivenNames],
       b.[Procedure], b.[Laterality], b.[Anaesthetic], b.[DurationMinutes], b.[Status], b.[IsTentative], b.[Payment], b.[TheatreIn], b.[TheatreOut],
       CASE WHEN b.[TheatreIn] IS NOT NULL AND b.[TheatreOut] IS NOT NULL THEN DATEDIFF(minute, b.[TheatreIn], b.[TheatreOut]) END AS ActualMinutes,
       b.[ScopeId], b.[CreatedAt], b.[CreatedBy]
FROM [theatre].[Bookings] b
JOIN [theatre].[Sessions] s ON s.[Id] = b.[SessionId]
JOIN [patients].[Patients] p ON p.[Id] = b.[PatientId]
JOIN [core].[Clinicians] su ON su.[Id] = s.[SurgeonId]
LEFT JOIN [core].[Clinicians] an ON an.[Id] = s.[AnaesthetistId]
LEFT JOIN [core].[Locations] l ON l.[Id] = s.[LocationId];
GO

CREATE OR ALTER VIEW [reporting].[vAppointment] AS
SELECT a.[Id] AS AppointmentId, a.[Date], a.[StartTime], a.[DurationMinutes], a.[Kind], c.[Name] AS Clinician, a.[ClinicianId], l.[Name] AS Room, a.[NoCharge], a.[IsTentative], a.[Status],
       a.[PatientId], p.[Mrn], p.[Nhi], p.[FamilyName], p.[GivenNames]
FROM [theatre].[Appointments] a
JOIN [patients].[Patients] p ON p.[Id] = a.[PatientId]
JOIN [core].[Clinicians] c ON c.[Id] = a.[ClinicianId]
LEFT JOIN [core].[Locations] l ON l.[Id] = a.[LocationId];
GO

CREATE OR ALTER VIEW [reporting].[vWaitlist] AS
SELECT w.[Id] AS WaitlistId, w.[PatientId], p.[Mrn], p.[Nhi], p.[FamilyName], p.[GivenNames], w.[Procedure], w.[Service], c.[Name] AS Specialist, w.[SpecialistId], w.[Funder],
       CASE WHEN w.[Funder] = N'HealthNz' THEN 1 ELSE 0 END AS PubliclyFunded, w.[Priority], w.[AddedOn], w.[TargetDate], w.[Status], w.[HoldUntil], w.[BookedFor],
       DATEDIFF(day, w.[AddedOn], CAST(SYSDATETIME() AS date)) AS DaysWaiting,
       CASE WHEN w.[Status] = N'Waiting' AND w.[TargetDate] < CAST(SYSDATETIME() AS date) THEN 1 ELSE 0 END AS Overdue
FROM [referrals].[Waitlist] w
JOIN [patients].[Patients] p ON p.[Id] = w.[PatientId]
JOIN [core].[Clinicians] c ON c.[Id] = w.[SpecialistId];
GO

CREATE OR ALTER VIEW [reporting].[vInvoiceSummary] AS
WITH lines AS (
    SELECT l.[DocumentId], SUM(ROUND(l.[Quantity] * l.[UnitPrice], 2)) AS Net,
           SUM(CASE WHEN l.[GstApplicable] = 1 THEN ROUND(l.[Quantity] * l.[UnitPrice], 2) ELSE 0 END) AS GstableNet
    FROM [billing].[Lines] l GROUP BY l.[DocumentId]),
paid AS (SELECT [DocumentId], SUM([Amount]) AS Paid FROM [billing].[Payments] GROUP BY [DocumentId])
SELECT d.[Id] AS DocumentId, d.[Kind], d.[Number], d.[Status], d.[Payer], d.[PayerName], d.[IssuedOn], d.[DueOn], d.[PatientId], p.[Mrn], p.[FamilyName], p.[GivenNames],
       ISNULL(x.Net, 0) AS Net, ROUND(ISNULL(x.GstableNet, 0) * d.[GstPercent] / 100, 2) AS Gst,
       ISNULL(x.Net, 0) + ROUND(ISNULL(x.GstableNet, 0) * d.[GstPercent] / 100, 2) AS Total, ISNULL(y.Paid, 0) AS Paid,
       ISNULL(x.Net, 0) + ROUND(ISNULL(x.GstableNet, 0) * d.[GstPercent] / 100, 2) - ISNULL(y.Paid, 0) AS Balance
FROM [billing].[Documents] d
JOIN [patients].[Patients] p ON p.[Id] = d.[PatientId]
LEFT JOIN lines x ON x.[DocumentId] = d.[Id]
LEFT JOIN paid y ON y.[DocumentId] = d.[Id];
GO

CREATE OR ALTER VIEW [reporting].[vCredentialStatus] AS
SELECT c.[Id] AS ClinicianId, c.[Name] AS Clinician, c.[Type] AS ClinicianType, cr.[Type] AS CredentialType, cr.[Reference], cr.[Issuer], cr.[IssuedOn], cr.[ExpiresOn],
       DATEDIFF(day, CAST(SYSDATETIME() AS date), cr.[ExpiresOn]) AS DaysToExpiry,
       CASE WHEN cr.[ExpiresOn] IS NULL THEN N'Current' WHEN cr.[ExpiresOn] < CAST(SYSDATETIME() AS date) THEN N'Expired'
            WHEN cr.[ExpiresOn] <= DATEADD(day, ISNULL((SELECT TOP (1) s.[WarningDays] FROM [cred].[Settings] s), 60), CAST(SYSDATETIME() AS date)) THEN N'ExpiringSoon' ELSE N'Current' END AS [State],
       cr.[VerifiedBy], cr.[VerifiedAt]
FROM [core].[Clinicians] c
JOIN [cred].[Credentials] cr ON cr.[ClinicianId] = c.[Id]
WHERE c.[IsActive] = 1 AND cr.[IsActive] = 1;
GO

CREATE OR ALTER VIEW [reporting].[vRosterShift] AS
SELECT sh.[Id] AS ShiftId, sh.[Date], st.[Name] AS Staff, st.[Role], st.[PayrollCode], sh.[AllDay], sh.[Start], sh.[End], sh.[BreakMinutes], sh.[Area], sh.[IsTentative],
       CASE WHEN sh.[AllDay] = 1 OR sh.[Start] IS NULL OR sh.[End] IS NULL THEN 0
            ELSE CAST((DATEDIFF(minute, sh.[Start], sh.[End]) - sh.[BreakMinutes]) / 60.0 AS decimal(6, 2)) END AS Hours
FROM [roster].[Shifts] sh
JOIN [roster].[Staff] st ON st.[Id] = sh.[StaffId];
GO

-- Set-to-patient traceability: every sterile tray issued to a case, with its steriliser load (AS/NZS 5369 recall by load or by patient).
CREATE OR ALTER VIEW [reporting].[vTrayTrace] AS
SELECT i.IssuedAt, t.Barcode, s.Code AS TrayCode, s.Name AS TrayName, c.LoadNumber, c.StartedAt AS SterilisedAt, m.Name AS Steriliser, c.Release,
       i.BookingId, i.PatientId, p.Nhi, p.Mrn, i.IssuedBy, i.ReturnedAt
FROM [assets].[TrayIssues] i
JOIN [assets].[Trays] t ON t.Id = i.TrayInstanceId
JOIN [assets].[TraySets] s ON s.Id = t.TraySetId
LEFT JOIN [assets].[Cycles] c ON c.Id = i.CycleId
LEFT JOIN [assets].[Equipment] m ON m.Id = c.MachineId
LEFT JOIN [patients].[Patients] p ON p.Id = i.PatientId;
GO
-- Implant registry extract (recalls by product and lot).
CREATE OR ALTER VIEW [reporting].[vImplant] AS
SELECT im.ImplantedOn, si.Code, si.Name AS Implant, im.Lot, im.SerialNumber, im.Manufacturer, im.Site, im.PatientId, p.Nhi, p.Mrn, im.BookingId, im.RecordedBy
FROM [assets].[Implants] im
JOIN [assets].[StockItems] si ON si.Id = im.StockItemId
LEFT JOIN [patients].[Patients] p ON p.Id = im.PatientId;
GO
-- Equipment maintenance due (PPM, calibration, test-and-tag).
CREATE OR ALTER VIEW [reporting].[vMaintenanceDue] AS
SELECT e.AssetNumber, e.Name, e.Category, e.Status, mp.Kind, mp.NextDue, DATEDIFF(day, CAST(SYSDATETIME() AS date), mp.NextDue) AS DaysUntilDue
FROM [assets].[MaintenancePlans] mp
JOIN [assets].[Equipment] e ON e.Id = mp.EquipmentId
WHERE e.Status <> N'Retired';
GO
CREATE OR ALTER VIEW [reporting].[vAuditDaily] AS
SELECT CAST(a.[OccurredAt] AS date) AS [Day], a.[Action], a.[EntityType], COUNT_BIG(*) AS Events, COUNT(DISTINCT a.[UserId]) AS Users
FROM [core].[AuditEvents] a
GROUP BY CAST(a.[OccurredAt] AS date), a.[Action], a.[EntityType];
GO

-- ---------------------------------------------------------------------------------------------------------------
-- Reporting stored procedures
-- ---------------------------------------------------------------------------------------------------------------
CREATE OR ALTER PROCEDURE [reporting].[usp_TheatreList] @Date date
AS
BEGIN
    SET NOCOUNT ON;
    SELECT ListDate, Room, ListStart, ListEnd, Surgeon, Anaesthetist, CaseOrder, Mrn, Nhi, FamilyName, GivenNames, [Procedure], Laterality, Anaesthetic, DurationMinutes, [Status], IsTentative
    FROM [reporting].[vTheatreCase] WHERE ListDate = @Date AND ListCancelled = 0 AND [Status] NOT IN (N'Cancelled', N'DidNotAttend')
    ORDER BY Room, ListStart, CaseOrder;
END
GO

CREATE OR ALTER PROCEDURE [reporting].[usp_WaitlistOverdue] @PubliclyFundedOnly bit = 0
AS
BEGIN
    SET NOCOUNT ON;
    SELECT Specialist, [Priority], Mrn, Nhi, FamilyName, GivenNames, [Procedure], AddedOn, TargetDate, DaysWaiting, Funder
    FROM [reporting].[vWaitlist] WHERE Overdue = 1 AND (@PubliclyFundedOnly = 0 OR PubliclyFunded = 1)
    ORDER BY TargetDate;
END
GO

CREATE OR ALTER PROCEDURE [reporting].[usp_CredentialExpiries] @Days int = 60
AS
BEGIN
    SET NOCOUNT ON;
    SELECT Clinician, CredentialType, Reference, ExpiresOn, DaysToExpiry, [State]
    FROM [reporting].[vCredentialStatus] WHERE ExpiresOn IS NOT NULL AND ExpiresOn <= DATEADD(day, @Days, CAST(SYSDATETIME() AS date))
    ORDER BY ExpiresOn;
END
GO

CREATE OR ALTER PROCEDURE [reporting].[usp_RosterHours] @From date, @To date
AS
BEGIN
    SET NOCOUNT ON;
    SELECT Staff, [Role], PayrollCode, COUNT(CASE WHEN AllDay = 0 THEN 1 END) AS Shifts, SUM(Hours) AS Hours
    FROM [reporting].[vRosterShift] WHERE [Date] BETWEEN @From AND @To AND IsTentative = 0
    GROUP BY Staff, [Role], PayrollCode ORDER BY Staff;
END
GO

CREATE OR ALTER PROCEDURE [reporting].[usp_InvoicesOutstanding]
AS
BEGIN
    SET NOCOUNT ON;
    SELECT Number, IssuedOn, DueOn, Payer, PayerName, Mrn, FamilyName, GivenNames, Total, Paid, Balance,
           CASE WHEN DueOn < CAST(SYSDATETIME() AS date) THEN DATEDIFF(day, DueOn, CAST(SYSDATETIME() AS date)) ELSE 0 END AS DaysOverdue
    FROM [reporting].[vInvoiceSummary] WHERE Kind = N'Invoice' AND [Status] NOT IN (N'Draft', N'Void') AND Balance > 0
    ORDER BY DueOn;
END
GO

-- Privacy Officer: everyone who opened or changed a patient's record (Health Information Privacy Code requests).
CREATE OR ALTER PROCEDURE [reporting].[usp_PatientAccessReport] @PatientId uniqueidentifier, @From datetimeoffset = NULL, @To datetimeoffset = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT a.[Sequence], a.[OccurredAt], a.[UserId], a.[Action], a.[EntityType], a.[EntityId], a.[Reason], a.[Workstation]
    FROM [core].[AuditEvents] a
    WHERE a.[PatientId] = CONVERT(nvarchar(100), @PatientId) AND (@From IS NULL OR a.[OccurredAt] >= @From) AND (@To IS NULL OR a.[OccurredAt] < @To)
    ORDER BY a.[Sequence];
END
GO

-- ---------------------------------------------------------------------------------------------------------------
-- Maintenance: index upkeep (primary keys are GUIDs, so indexes fragment). Schedule weekly out of hours
-- (SQL Server Agent or Task Scheduler + sqlcmd). Reorganise 10–30 %, rebuild > 30 %, then update statistics.
-- ---------------------------------------------------------------------------------------------------------------
CREATE OR ALTER PROCEDURE [maintenance].[usp_IndexMaintenance] @MinPages int = 100, @WhatIf bit = 0
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @work TABLE (Id int IDENTITY PRIMARY KEY, [Sql] nvarchar(max), Fragmentation float, [Index] nvarchar(400));
    INSERT INTO @work ([Sql], Fragmentation, [Index])
    SELECT N'ALTER INDEX ' + QUOTENAME(i.[name]) + N' ON ' + QUOTENAME(s.[name]) + N'.' + QUOTENAME(t.[name])
           + CASE WHEN ps.avg_fragmentation_in_percent > 30 THEN N' REBUILD' ELSE N' REORGANIZE' END,
           ps.avg_fragmentation_in_percent, s.[name] + N'.' + t.[name] + N'.' + i.[name]
    FROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, N'LIMITED') ps
    JOIN sys.indexes i ON i.[object_id] = ps.[object_id] AND i.index_id = ps.index_id
    JOIN sys.tables t ON t.[object_id] = i.[object_id]
    JOIN sys.schemas s ON s.[schema_id] = t.[schema_id]
    WHERE ps.page_count >= @MinPages AND ps.avg_fragmentation_in_percent >= 10 AND i.index_id > 0 AND t.is_ms_shipped = 0;
    IF @WhatIf = 1 BEGIN SELECT [Index], Fragmentation, [Sql] FROM @work; RETURN; END
    DECLARE @i int = 1, @n int = (SELECT COUNT(*) FROM @work), @sql nvarchar(max);
    WHILE @i <= @n
    BEGIN
        SELECT @sql = [Sql] FROM @work WHERE Id = @i;
        BEGIN TRY EXEC (@sql); END TRY BEGIN CATCH PRINT N'Skipped: ' + @sql + N' – ' + ERROR_MESSAGE(); END CATCH
        SET @i += 1;
    END
    EXEC sp_updatestats;
    SELECT @n AS IndexesMaintained;
END
GO

-- ---------------------------------------------------------------------------------------------------------------
-- Read-only reporting role: SELECT on the views and EXECUTE on the reporting procedures only – no access to the
-- underlying tables (ownership chaining through dbo). Add report users/groups to this role.
-- ---------------------------------------------------------------------------------------------------------------
IF DATABASE_PRINCIPAL_ID(N'brightpas_reporting') IS NULL CREATE ROLE [brightpas_reporting] AUTHORIZATION [dbo];
GRANT SELECT ON SCHEMA::[reporting] TO [brightpas_reporting];
GRANT EXECUTE ON SCHEMA::[reporting] TO [brightpas_reporting];
GO
